/**
 * api.js — Axios instance.
 * Purpose:        Centralised HTTP client for all API calls.
 * Responsibility: Base URL, auth header injection, error normalisation.
 */
import axios from 'axios';

const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:8080/k2-fast-foods/backend/public/api/v1',
  timeout: 10000,
  headers: { 'Content-Type': 'application/json' },
});

// Inject JWT token on every request
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('k2_token');
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

// Normalise error responses
api.interceptors.response.use(
  (res) => res,
  (err) => {
    if (err.response?.status === 401) {
      localStorage.removeItem('k2_token');
      localStorage.removeItem('k2_user');
      window.location.href = '/login';
    }
    return Promise.reject(err);
  }
);

export default api;
